"""Transparent heuristic checks; not an official compliance determination."""
PATHWAYS = {"new":"New Institution Approval", "existing":"Existing Institution / EoA", "expansion":"Course or Intake Expansion", "change":"Institutional Change / Conversion"}
COMMON = [("application", "Application form / covering letter", ["application form", "covering letter", "application"]), ("identity", "Institution identity and address", ["institution", "address", "campus", "sponsoring body"])]
RULES = {
"new": [("land","Land / lease / building evidence",["land","lease","building","ownership","sale deed"]),("plan","Approved plan / occupancy evidence",["building plan","occupancy","completion certificate","approved plan"]),("finance","Financial capacity / audited statements",["audited","balance sheet","financial statement","bank statement"]),("faculty","Faculty and staffing plan",["faculty","teaching staff","staffing pattern"]),("infra","Infrastructure and laboratory details",["laboratory","library","infrastructure","equipment"]),("statutory","Applicable statutory approvals / NOCs",["noc","fire","building safety","statutory approval"])],
"existing": [("approval","Prior approval / EoA records",["extension of approval","eoa","approval letter"]),("faculty","Faculty and staff records",["faculty","staff","appointment","qualification"]),("infra","Infrastructure / facilities evidence",["laboratory","library","infrastructure","equipment"]),("compliance","Previous compliance / action taken",["compliance","action taken","undertaking","show cause"]),("students","Student and intake information",["student","enrolment","intake","admission"])],
"expansion": [("current","Current approval and sanctioned intake",["approval letter","eoa","sanctioned intake","approved intake"]),("need","Proposed programme / intake justification",["proposed intake","additional intake","new programme","justification"]),("faculty","Faculty availability for proposed intake",["faculty","staff","appointment"]),("infra","Infrastructure capacity evidence",["laboratory","library","classroom","infrastructure"]),("regulatory","Applicable programme-specific approvals",["regulatory approval","noc","approval"])],
"change": [("approval","Existing institution approval records",["approval letter","eoa","approval"]),("governance","Management / governing-body resolution",["resolution","governing body","board meeting","management"]),("legal","Legal entity / trust / society documents",["trust deed","society","registration certificate","section 8"]),("continuity","Student, faculty and asset continuity plan",["continuity","student","faculty","assets","transfer"]),("permissions","Applicable permission / NOC evidence",["permission","noc","consent","approval"])]}
def evaluate(pathway, docs):
    corpus = "\n".join(d.get("text", "") for d in docs).lower()
    out=[]
    for key,title,terms in COMMON + RULES.get(pathway, RULES["new"]):
        hits=[t for t in terms if t in corpus]
        out.append({"key":key,"title":title,"status":"possible_evidence" if hits else "not_detected","confidence":min(.88,.55+.08*len(hits)) if hits else .72,"evidence":", ".join(hits[:5]) if hits else "No matching terms detected in extracted text.","explanation":"Related terms were found. Reviewer must confirm relevance, validity, dates and applicability." if hits else "Potential gap only: evidence may be scanned, worded differently, or stored separately."})
    return out
